/* Mini output worklet: low-jitter PCM16 24kHz -> browser device sampleRate.
 * Flushes immediately on barge-in; reports actually consumed audio, not
 * text generated by the LLM. It never synthesizes a voice locally.
 */
class MiniPlaybackProcessor extends AudioWorkletProcessor {
  constructor(options) {
    super();
    this.sourceRate = options.processorOptions?.sourceRate || 24000;
    this.capacity = this.sourceRate * 5;
    this.frames = new Int16Array(this.capacity);
    this.read = 0;
    this.write = 0;
    this.count = 0;
    this.fraction = 0;
    this.started = false;
    this.played = 0;
    this.reported = 0;
    this.receivedEnd = false;
    this.port.onmessage = (event) => {
      const data = event.data || {};
      if (data.type === 'flush') {
        this.read = this.write = this.count = 0;
        this.fraction = 0;
        this.started = false;
        this.played = this.reported = 0;
        this.receivedEnd = false;
      } else if (data.type === 'end') {
        this.receivedEnd = true;
        if (this.count === 0) this.port.postMessage({type:'playback.drain', milliseconds: Math.floor(1000*this.played/this.sourceRate)});
      } else if (data.type === 'chunk') {
        const input = data.pcm instanceof Int16Array
          ? data.pcm : new Int16Array(data.pcm);
        if (input.length > this.capacity - this.count) {
          this.port.postMessage({type:'overflow'});
          return;
        }
        for (let i = 0; i < input.length; i++) {
          this.frames[this.write] = input[i];
          this.write = (this.write + 1) % this.capacity;
          this.count++;
        }
      }
    };
  }
  process(_inputs, outputs) {
    const out = outputs[0]?.[0];
    if (!out) return true;
    out.fill(0);
    if (!this.started && this.count >= this.sourceRate * 0.06) {
      this.started = true;
      this.port.postMessage({type:'playback.started'});
    }
    if (!this.started) return true;
    const step = this.sourceRate / sampleRate;
    for (let i = 0; i < out.length; i++) {
      if (this.count < 2) {
        if (this.count === 1) {
          out[i] = this.frames[this.read] / 32768;
          this.read = (this.read + 1) % this.capacity;
          this.count = 0;
          this.played++;
        }
        this.started = false;
        this.fraction = 0;
        if (this.receivedEnd) {
          this.receivedEnd = false;
          this.port.postMessage({type:'playback.drain',
            milliseconds: Math.floor(1000 * this.played / this.sourceRate)});
        }
        break;
      }
      const first = this.frames[this.read] / 32768;
      const second = this.frames[(this.read + 1) % this.capacity] / 32768;
      out[i] = first + (second - first) * this.fraction;
      this.fraction += step;
      const consumed = Math.floor(this.fraction);
      if (consumed) {
        const take = Math.min(consumed, this.count - 1);
        this.read = (this.read + take) % this.capacity;
        this.count -= take;
        this.played += take;
        this.fraction -= take;
      }
    }
    if (this.played - this.reported >= this.sourceRate / 10) {
      this.reported = this.played;
      this.port.postMessage({type:'playback.progress',
        milliseconds: Math.floor(1000 * this.played / this.sourceRate)});
    }
    return true;
  }
}
registerProcessor('mini-playback', MiniPlaybackProcessor);
